from typing import List, Tuple

def process_queries(queries: List[Tuple[int, int]]) -> List[int]:
    A = []
    results = []
    for query, num in queries:
        if query == 1:
            A.append(num)
        elif query == 2:
            if num <= len(A):
                results.append(A[-num])
    return results
